using MediatR; using VetCommission.Application.Common.Errors; using VetCommission.Application.Common.Results; using VetCommission.Application.Features.Auth.Tenant;
namespace VetCommission.Application.Features.ProcedureCategories;
public sealed record GetProcedureCategoryQuery(Guid Id):IRequest<NotificationResult<ProcedureCategoryDto>>;
public sealed class GetProcedureCategoryHandler(IProcedureCategoryRepository repo,ITenantContext tenant,IClinicContext clinic):IRequestHandler<GetProcedureCategoryQuery,NotificationResult<ProcedureCategoryDto>>{public async Task<NotificationResult<ProcedureCategoryDto>> Handle(GetProcedureCategoryQuery r,CancellationToken c){if(tenant.TenantId is not Guid t||clinic.ClinicId is not Guid k)return NotificationResult<ProcedureCategoryDto>.Failure(new NotificationError(ErrorCodes.Forbidden,"Contexto ativo obrigatorio."));var v=await repo.GetAsync(t,k,r.Id,c);return v is null?NotificationResult<ProcedureCategoryDto>.Failure(new NotificationError(ErrorCodes.NotFound,"Categoria nao encontrada.")):NotificationResult<ProcedureCategoryDto>.Success(v);}}
